    TopModule dut (
        .y  (y),
        .w  (w),
        .Y1 (Y1),
        .Y3 (Y3)
    );

    integer errors = 0;
    reg [1:0] exp_Y1_Y3;

    // Task to check outputs against expected values
    task check_outputs(input [1:0] expected);
        begin
            #1; // Allow combinational propagation
            if ({Y1, Y3} !== expected) begin
                $display("ERROR: y=%b, w=%b | Got Y1=%b, Y3=%b | Expected Y1=%b, Y3=%b",
                         y, w, Y1, Y3, expected[1], expected[0]);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize inputs
        y = 7'b0000000;
        w = 1'b0;
        #10;

        // Test vectors covering all one-hot states and w combinations
        // State A: y[0] = 1 (7'b0000001)
        y = 7'b0000001; w = 0; check_outputs(2'b10); // Y1=1, Y3=0
